#!/usr/bin/env bash
# Generated by the ai-plugin-sdk build. Edit the plugin's own sources instead.

# The answers of every hook on one tool call, on standard input, one to a line.
# Prints the one that wins: the first deny, else the first ask, else the first
# allow, else nothing, which leaves the call to the client's own rules.
#
# Claude Code and Codex merge the answers themselves, in this order. Where the
# SDK runs the hooks itself, this is the merge.
strongest_permission() {
  local answers decision
  answers="$(cat)"
  for decision in deny ask allow; do
    printf '%s\n' "$answers" \
      | grep --max-count=1 --extended-regexp "\"permissionDecision\"[[:space:]]*:[[:space:]]*\"$decision\"" \
      && return 0
  done
  return 0
}
